using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var apiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model   = Environment.GetEnvironmentVariable("OPENAI_MODEL")   ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable.");
    return 1;
}

// ── Notebook (in-memory note store used by the agent) ──────────────────────────
var notebook = new List<(string Title, string Content)>();

// ── Tool definitions ───────────────────────────────────────────────────────────

[Description("Search the web for a query and return a list of result snippets. Use this to find information about any topic.")]
string SearchWeb([Description("The search query")] string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    // Use DuckDuckGo Lite (HTML) — no API key required.
    var url = $"https://lite.duckduckgo.com/lite/?q={Uri.EscapeDataString(query)}";
    var html = http.GetStringAsync(url).GetAwaiter().GetResult();

    // Pull result snippets from the response table rows.
    var snippets = new List<string>();
    foreach (Match m in Regex.Matches(html,
        @"<td[^>]*class=""result-snippet""[^>]*>(.*?)</td>",
        RegexOptions.Singleline | RegexOptions.IgnoreCase))
    {
        var text = Regex.Replace(m.Groups[1].Value, "<.*?>", "").Trim();
        text = WebUtility.HtmlDecode(text);
        if (!string.IsNullOrWhiteSpace(text))
            snippets.Add(text);
    }

    // Also grab link titles for additional context.
    foreach (Match m in Regex.Matches(html,
        @"<a[^>]+rel=""nofollow""[^>]*>(.*?)</a>",
        RegexOptions.Singleline | RegexOptions.IgnoreCase))
    {
        var text = Regex.Replace(m.Groups[1].Value, "<.*?>", "").Trim();
        text = WebUtility.HtmlDecode(text);
        if (!string.IsNullOrWhiteSpace(text) && text.Length > 10)
            snippets.Add($"[Link] {text}");
    }

    if (snippets.Count == 0)
        return "No results found.";

    // Return up to 10 results.
    return string.Join("\n---\n", snippets.Take(10));
}

[Description("Save a research note for later reference. Use this to record key findings as you research.")]
string TakeNote(
    [Description("Short title for the note")] string title,
    [Description("Detailed content of the note")] string content)
{
    notebook.Add((title, content));
    return $"Note #{notebook.Count} saved: \"{title}\"";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notebook.Count == 0)
        return "No notes saved yet.";

    var sb = new StringBuilder();
    for (var i = 0; i < notebook.Count; i++)
        sb.AppendLine($"## Note {i + 1}: {notebook[i].Title}\n{notebook[i].Content}\n");
    return sb.ToString();
}

// ── Build the AI chat client with tool support ─────────────────────────────────
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()   // automatically invokes tools when the model requests them
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(TakeNote),
    AIFunctionFactory.Create(GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ── Prompt ──────────────────────────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  Research Agent  🔍           ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic and the agent will:      ║");
Console.WriteLine("║  • Search the web for information       ║");
Console.WriteLine("║  • Take notes on key findings           ║");
Console.WriteLine("║  • Produce a summary with sources       ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\nResearching \"{topic}\" — this may take a moment...\n");

// ── Agent system prompt ────────────────────────────────────────────────────────
var systemPrompt = """
    You are a research agent. Your goal is to thoroughly research the user's topic
    and produce an informative summary.

    Workflow:
    1. Break the topic into 2-3 key search queries.
    2. For each query, call SearchWeb and review the results.
    3. Use TakeNote to save the most important findings (facts, statistics, quotes).
    4. After gathering enough information, call GetNotes to review all your notes.
    5. Produce a well-structured summary with:
       - An overview paragraph
       - Key findings as bullet points
       - A brief conclusion

    Always search at least twice with different queries to get broad coverage.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic: {topic}"),
};

// ── Agent loop ─────────────────────────────────────────────────────────────────
const int maxIterations = 15;
string? finalAnswer = null;

for (var i = 0; i < maxIterations; i++)
{
    var response = await chatClient.GetResponseAsync(messages, chatOptions);

    // Append the full response (including any tool-call / tool-result messages)
    // back to the conversation for multi-turn.
    messages.AddMessages(response);

    // Log tool activity to the console.
    foreach (var msg in response.Messages)
    {
        if (msg.Role == ChatRole.Assistant)
        {
            foreach (var item in msg.Contents)
            {
                if (item is FunctionCallContent fc)
                    Console.WriteLine($"  🔧 Calling {fc.Name}({Summarize(fc.Arguments)})");
            }
        }
    }

    // Check if the model produced a final text answer (no pending tool calls).
    var last = response.Messages.LastOrDefault(m => m.Role == ChatRole.Assistant);
    if (last is not null)
    {
        var hasPendingCalls = last.Contents.OfType<FunctionCallContent>().Any();
        var textContent = last.Text;

        if (!hasPendingCalls && !string.IsNullOrWhiteSpace(textContent))
        {
            finalAnswer = textContent;
            break;
        }
    }
}

// ── Output ─────────────────────────────────────────────────────────────────────
Console.WriteLine("\n════════════════════════════════════════════");
Console.WriteLine("  📝  Research Summary");
Console.WriteLine("════════════════════════════════════════════\n");
Console.WriteLine(finalAnswer ?? "The agent could not complete the research.");
Console.WriteLine();

return 0;

// ── Helpers ────────────────────────────────────────────────────────────────────
static string Summarize(IDictionary<string, object?>? args)
{
    if (args is null || args.Count == 0) return "";
    var parts = args.Select(kv =>
    {
        var val = kv.Value?.ToString() ?? "";
        if (val.Length > 60) val = val[..57] + "...";
        return $"{kv.Key}: \"{val}\"";
    });
    return string.Join(", ", parts);
}

